from core import *

def papers():
 p=[]
 p.append(item('What is 48 + 199?',247,'Adding 199 is the same as adding 200 and subtracting 1. Thus 48+200−1=247.','DIG-01',[237,246,248,257],check=48+199))
 p.append(item('A pizza is divided into eight equal pieces. Three pieces are eaten. What fraction remains?','5/8','Eight pieces minus three eaten leaves five. Each piece is one eighth of the whole pizza, so five eighths remain.','FRAC-01',['3/8','3/5','1/2','5/3'],check=str(F(8-3,8))))
 p.append(item('There are 24 legs altogether on some identical four-legged stools. How many stools are there?',6,'Each stool contributes four legs. Divide the total by four: 24÷4=6 stools.','ALG-01',[4,5,8,12],check=24//4))
 p.append(item('Which of these numbers is closest to 500?',497,'The distances from 500 are: 497 is 3 away, 492 is 8 away, 506 is 6 away, 485 is 15 away, and 512 is 12 away. The smallest distance is 3.','DIG-01',[492,506,485,512]))
 p.append(item('A square tile is turned through 90° about its centre. How many of its corners occupy positions that were corners before the turn?',4,'A quarter turn sends every corner of a square to the next corner’s former position. All four corner positions are occupied again.','SPATIAL-02',[0,1,2,3]))
 p.append(item('The chart shows votes for four activities. How many votes were cast altogether?',50,'Add the four labelled counts: 14+9+16+11=50. Each vote contributes to one activity, so no adjustment for overlap is needed.','DATA-03',[40,45,48,54],check=14+9+16+11,figure=bars([14,9,16,11],['Art','Chess','Sport','Music'])))
 p.append(item('One packet contains 250 g of flour. How many packets contain 2 kg of flour?',8,'Two kilograms is 2000 grams. Divide by 250 grams per packet: 2000÷250=8 packets.','RATE-01',[4,5,6,10],check=2000//250))
 p.append(item('A lift starts on floor 4, goes up 7 floors, then down 3 floors. On which floor does it stop?',8,'Track the two changes in order: 4+7=11, then 11−3=8. Its net movement is four floors upwards.','ALG-01',[7,9,10,14],check=4+7-3))
 p.append(item('An isosceles triangle has two equal sides of 9 cm and a third side of 6 cm. What is its perimeter?', '24 cm','The perimeter includes all three sides: 9+9+6=24 cm. The equal sides must both be counted.','GEO-01',['15 cm','18 cm','21 cm','27 cm']))
 p.append(item('A string of beads repeats red, yellow, blue, green, white. What colour is bead 32?','Yellow','Thirty beads make six complete five-bead blocks. Bead 32 is the second bead in the next block, which is yellow.','SEQ-02',['Red','Blue','Green','White']))
 p.append(item('In a box of 48 chocolates, one quarter contain nuts and one third contain caramel. No chocolate contains both. How many contain neither?',20,'The nut chocolates number 48÷4=12; the caramel chocolates number 48÷3=16. Since they do not overlap, 48−12−16=20 contain neither.','FRAC-01',[16,18,24,28],check=48-48//4-48//3))
 p.append(item('An adult ticket costs twice a child ticket. Two adult tickets and three child tickets cost $56. What does one child ticket cost?','$8','Replace each adult ticket by two child-ticket units. The total is 2×2+3=7 units, costing $56. One child ticket costs 56÷7=$8.','ALG-02',['$7','$9','$12','$16']))
 p.append(item('A rectangular path measures 14 m by 6 m. A runner completes five laps. How far does the runner travel?', '200 m','One lap is the perimeter, 2×(14+6)=40 m. Five laps cover 5×40=200 m.','GEO-01',['100 m','140 m','180 m','420 m']))
 p.append(item('The sum of two numbers is 70. One is four times the other. What is the larger number?',56,'The smaller number is one unit and the larger four units. Five units total 70, so one unit is 14 and the larger is 4×14=56.','ALG-02',[14,35,42,60],check=70//5*4))
 p.append(item('A regular pentagon and a regular triangle share a side. What is the sum of their numbers of sides, counting the shared side only once?',7,'The pentagon has 5 sides and the triangle 3. Adding gives 8 appearances, but the shared segment appears twice. Count it once by subtracting 1: 7 distinct segments.','COUNT-04',[6,8,9,10],check=5+3-1))
 p.append(item('A number leaves remainder 4 when divided by 9. What remainder does twice the number leave when divided by 9?',8,'Write the number as 9k+4. Twice it is 18k+8, which is a multiple of 9 plus 8. Hence the remainder is 8.','DIV-03',[0,1,2,4],check=2*4%9))
 p.append(item('A rectangle is 3 times as long as it is wide. Its perimeter is 64 cm. What is its area?', '192 cm²','If the width is w, the length is 3w. Perimeter is 2(w+3w)=8w=64, so w=8 and length=24. Area is 8×24=192 cm².','GEO-05',['128 cm²','144 cm²','256 cm²','384 cm²']))
 p.append(item('A class has 12 boys and 18 girls. After some boys join, boys make up half the class. How many boys joined?',6,'The number of girls stays 18. For boys to be half the class, there must also be 18 boys. Therefore 18−12=6 boys joined.','FRAC-02',[3,4,9,12],check=18-12))
 p.append(item('How many positive whole numbers less than 50 have exactly one digit equal to 4?',13,'The numbers 4,14,24,34 contribute four. In 40–49, all except 44 have exactly one 4, contributing nine. Thus 4+9=13.','DIG-03',[12,14,15,16],check=sum(str(n).count('4')==1 for n in range(1,50))))
 p.append(item('A shop opens for 7 hours. It serves one customer every 12 minutes, with the first customer at opening time and the last exactly at closing. How many customers are served?',36,'Seven hours is 420 minutes, containing 420÷12=35 gaps between customers. Including both endpoints gives 35+1=36 customers.','RATE-01',[34,35,37,42],check=7*60//12+1))
 p.append(item('A rectangle is divided into a 2-by-3 grid of equal squares. How many rectangles of any size have sides on the grid lines?',18,'There are four vertical lines, so choose two in 6 ways. There are three horizontal lines, so choose two in 3 ways. Each choice gives one rectangle: 6×3=18.','COUNT-05',[6,12,15,24],check=math.comb(4,2)*math.comb(3,2),figure=grid(3,2)))
 p.append(item('A can holds 900 mL when full. It is two thirds full. After 150 mL is poured out, what percentage of the can is full?',50,'Two thirds of 900 mL is 600 mL. After pouring out 150 mL, 450 mL remains. This is 450/900=1/2=50% of the full can.','FRAC-03',[40,45,60,75],check=(900*2//3-150)*100//900))
 p.append(item('A square and an equilateral triangle have equal perimeters. The square has area 81 cm². How long is one side of the triangle?', '12 cm','The square’s side is 9 cm, so its perimeter is 36 cm. The equilateral triangle has three equal sides with that same total, giving 36÷3=12 cm.','GEO-05',['9 cm','10 cm','18 cm','27 cm']))
 p.append(item('A fair coin is tossed four times. How many ordered outcomes contain more heads than tails?',5,'More heads than tails means either three heads or four heads. The single tail can occupy any of four positions, and the all-heads outcome gives one more. Thus there are 4+1=5 outcomes.','DATA-01',[4,6,8,10],check=sum(sum(z)>2 for z in product([0,1],repeat=4))))
 p.append(item('A number has prime factorisation 2³ × 3². How many of its positive divisors are even?',9,'An even divisor must use 2 to power 1,2 or 3: three choices. It may use 3 to power 0,1 or 2: another three choices. Thus 3×3=9 divisors are even.','DIV-01',[6,8,10,12],check=sum(d%2==0 for d in divisors(72))))
 p.append(item('A rectangle has whole-number side lengths. Its area and perimeter have the same numerical value. How many different rectangles are possible, counting rotations as the same?',2,'Let the sides be a≤b. The equation ab=2a+2b becomes (a−2)(b−2)=4. Positive sides force both a,b>2. The factor pairs of 4 are (1,4) and (2,2), giving rectangles 3×6 and 4×4. Hence two rectangles work.','GEO-05',check=sum(a*b==2*(a+b) for a in range(1,20) for b in range(a,20))))
 p.append(item('A route uses six right steps and five up steps. No two up steps may be consecutive. How many different orders of the eleven steps are possible?',21,'Place the six right steps first. They create seven gaps, including before the first and after the last. Put one up step into each of five chosen gaps so that no up steps touch. Choose five of seven gaps: 7×6÷2=21.','COUNT-02',check=math.comb(7,5)))
 p.append(item('For a positive integer n, n! means 1×2×…×n. What is the remainder when 1!+2!+3!+…+10! is divided by 100?',13,'Every factorial from 10! onward contains two factors of 5 and enough factors of 2, so 10! contributes remainder 0. The remainders of 1! to 9! modulo 100 are 1,2,6,24,20,20,40,20,80. Their sum is 213, whose remainder is 13. Multiplying each previous remainder by the next integer makes this calculation small.','DIV-05',check=sum(math.factorial(i) for i in range(1,11))%100))
 p.append(item('The numbers 1 to 6 are placed in six numbered positions around a circle. The sum of neighbouring numbers must never be prime. How many arrangements are possible? The positions are fixed, so rotations count as different.',12,'Number 1 can neighbour only 3 and 5, because its other possible sums are prime. Number 2 can neighbour only 4 and 6. Joining these two forced chains into a single circle requires 3 next to 6 and 5 next to 4; linking 3 to 5 would close a three-number circle. The only circular order is 1,3,6,2,4,5, or its reverse. Six rotations of each give 12 arrangements.','LOGIC-02',check=sum(all(z[i]+z[(i+1)%6] not in [3,5,7,11] for i in range(6)) for z in permutations(range(1,7)))))
 rows=[r for r in product(range(4),repeat=3) if sum(r)==6]
 p.append(item('Each cell of a 3-by-3 grid contains 0, 1, 2 or 3. Every row and every column must sum to 6. How many grids are possible? Rotations and reflections count as different.',55,'Replace every entry x by 3−x. This gives a one-to-one correspondence with grids whose row and column sums are 3. Classify their top row. A permutation of (3,0,0) has 3 positions and 4 possible second rows, contributing 12. A permutation of (2,1,0) has 6 positions and 6 possible second rows, contributing 36: for top (2,1,0), second-row first entry 0 allows (0,0,3),(0,1,2),(0,2,1); first entry 1 allows (1,0,2),(1,1,1),(1,2,0). Top (1,1,1) allows 7 second rows: permutations of (0,1,2) and (1,1,1). Each third row is forced. Total 12+36+7=55.','COUNT-06',check=sum(all(sum(z[y][x] for y in range(3))==6 for x in range(3)) for z in product(rows,repeat=3)),figure=grid(3,3)))
 one=paper('amc',5,p)
 p=[]
 p.append(item('What is 7 × 8 + 6?',62,'Multiplication is performed before addition. First 7×8=56, then 56+6=62.','DIG-01',[56,60,64,98],check=7*8+6))
 p.append(item('A book costs $7.50. How much do four books cost?','$30','Two books cost $15, so four books cost twice that: $30. Equivalently, 4×750 cents=3000 cents.','DIG-01',['$22.50','$28','$32','$35']))
 p.append(item('A shape has exactly three straight sides. What is it called?','Triangle','A polygon with three straight sides is a triangle. The side lengths and angles may vary, but the side count determines this name.','GEO-01',['Quadrilateral','Pentagon','Hexagon','Circle']))
 p.append(item('What number is missing from 18, 24, 30, □, 42?',36,'Each step adds 6: 18→24→30. Adding another 6 gives 36, and 36+6=42 confirms the pattern.','SEQ-01',[32,34,38,40],check=30+6))
 p.append(item('A jug contains 1 litre of juice. Two glasses each holding 180 mL are filled from it. How much juice remains?', '640 mL','One litre is 1000 mL. Two glasses use 360 mL, leaving 1000−360=640 mL.','RATE-01',['460 mL','620 mL','660 mL','820 mL']))
 p.append(item('Which number is divisible by both 2 and 5?',130,'A number divisible by both 2 and 5 is a multiple of 10 and ends in 0. Of these options, only 130 does.','DIV-01',[125,132,145,152]))
 p.append(item('A square has side 11 cm. What is the distance around it?', '44 cm','A square has four equal sides. Its perimeter is 4×11=44 cm. Area would use a different calculation.','GEO-01',['22 cm','33 cm','48 cm','121 cm']))
 p.append(item('A coach leaves at 8:25 am and arrives at 9:10 am. How long is the journey?', '45 minutes','From 8:25 to 9:00 is 35 minutes, and from 9:00 to 9:10 is 10 minutes. Together they make 45 minutes.','RATE-01',['35 minutes','40 minutes','55 minutes','85 minutes']))
 p.append(item('The table shows goals in four matches. In how many matches were more than three goals scored?',2,'More than three excludes a score of exactly three. Only the matches with 5 and 4 goals qualify, so there are two.','DATA-03',[0,1,3,4],check=sum(v>3 for v in [2,5,3,4]),figure=table_diagram([['1',2],['2',5],['3',3],['4',4]],['Match','Goals'])))
 p.append(item('A strip is divided into ten equal parts. Seven are shaded. What percentage is shaded?',70,'Seven out of ten equals 7/10. Multiplying numerator and denominator by 10 gives 70/100, or 70%.','FRAC-03',[7,30,60,75],check=7*10,figure=grid(10,1,[(x,0) for x in range(7)])))
 p.append(item('Two whole numbers multiply to 84 and differ by 5. What is their sum?',19,'Check factor pairs of 84. The pair 7 and 12 differs by 5. Their sum is 19; the other factor pairs have different gaps.','ALG-03',[17,18,20,25],check=7+12))
 p.append(item('A recipe for six people uses 450 g of rice. At the same rate, how much rice is needed for ten people?', '750 g','One person’s share is 450÷6=75 g. Ten shares require 10×75=750 g.','FRAC-02',['600 g','675 g','800 g','900 g']))
 p.append(item('A rectangular sheet has perimeter 50 cm and length 16 cm. What is its width?', '9 cm','Half the perimeter is length plus width: 25 cm. Subtract the length: 25−16=9 cm.','GEO-01',['8 cm','10 cm','18 cm','34 cm']))
 p.append(item('A box contains red and green marbles. The probability of choosing red is 3/7. There are 16 green marbles. How many marbles are in the box?',28,'Green accounts for 4/7 of the box. Four parts equal 16, so one part is 4 marbles. The whole seven parts contain 28 marbles.','DATA-01',[21,24,32,36],check=16//4*7))
 p.append(item('Three consecutive even numbers sum to 84. What is the smallest?',26,'The middle is their mean, 84÷3=28. Consecutive even numbers differ by 2, so the numbers are 26,28,30.','SEQ-01',[24,27,28,30],check=84//3-2))
 p.append(item('A regular hexagon is divided by joining its centre to all six vertices. What is the size of each angle at the centre?', '60°','The six equal central angles fill a full turn of 360°. Each is 360÷6=60°.','GEO-03',['30°','45°','90°','120°'],figure=svg('<polygon points="90,120 150,35 270,35 330,120 270,205 150,205" fill="#d9ebe8"/><path d="M210,120L90,120 M210,120L150,35 M210,120L270,35 M210,120L330,120 M210,120L270,205 M210,120L150,205"/>')))
 p.append(item('A number machine changes x into 3x−2. What input produces the same output as input 8 produces after passing through the machine twice?',22,'The first pass gives 3×8−2=22, and the second gives 3×22−2=64. To produce 64 in one pass, the input must be 22. Recognising the intermediate value avoids unnecessary algebra.','ALG-04',[20,24,62,64],check=3*8-2))
 p.append(item('How many different amounts can be made using at least one of three coins worth 10 cents, 20 cents and 50 cents, using each coin at most once?',7,'There are 2³=8 choices of which coins to use, including using none. The seven nonempty choices give different totals: 10,20,30,50,60,70,80 cents. Thus there are seven amounts.','COUNT-01',[3,5,6,8],check=len({10*a+20*b+50*c for a,b,c in product([0,1],repeat=3)})-1))
 p.append(item('A car travels 84 km using 6 litres of fuel. At the same rate, how many litres are needed for 210 km?',15,'The car travels 84÷6=14 km per litre. Therefore 210÷14=15 litres are needed.','RATE-03',[12,14,16,18],check=210//(84//6)))
 p.append(item('In a group of 40 children, 26 play tennis and 22 swim. Everyone does at least one. How many do exactly one activity?',32,'The overlap is 26+22−40=8 children. Remove those eight from the whole group to count children doing exactly one activity: 40−8=32.','COUNT-04',[8,24,30,34],check=2*40-26-22))
 p.append(item('A rectangle is 8 cm by 5 cm. Its length and width are both increased by the same whole number of centimetres. Its new area is 88 cm². What is its new perimeter?', '38 cm','Try the increase x in (8+x)(5+x)=88. An increase of 3 gives 11×8=88; smaller or larger increases give smaller or larger areas. The new perimeter is 2(11+8)=38 cm.','GEO-05',['26 cm','32 cm','36 cm','44 cm']))
 p.append(item('The mean of six numbers is 14. Removing one number makes the mean of the remaining five numbers 12. What number was removed?',24,'The original total is 6×14=84. The remaining total is 5×12=60. Their difference, 24, is the removed number.','DATA-02',[12,14,20,26],check=6*14-5*12))
 p.append(item('A square piece of paper is folded in half. A single straight cut, parallel to the fold and between the fold and the open edge, goes all the way across the folded paper. How many separate pieces are there after unfolding?',3,'The cut passes through two layers and makes two parallel cuts on the original sheet, one on either side of the fold. These divide the sheet into three strips.','SPATIAL-03',[1,2,4,5]))
 p.append(item('A train leaves every 18 minutes and a ferry every 24 minutes. They depart together at 9:00 am. How many train departures occur strictly between that time and their next simultaneous departure?',3,'The next joint departure is after lcm(18,24)=72 minutes. Train departures strictly inside the interval are at 18,36,54 minutes: three. The 72-minute departure is excluded.','DIV-02',[2,4,5,6],check=math.lcm(18,24)//18-1))
 p.append(item('A 3 cm by 4 cm rectangle is enlarged so that every length is multiplied by 3. By what factor is its area multiplied?',9,'The original area is 12 cm². The enlarged dimensions are 9 and 12 cm, giving area 108 cm². The area factor is 108÷12=9, because both dimensions gained a factor of 3.','GEO-02',[3,6,12,27],check=3**2))
 p.append(item('How many positive divisors of 360 are perfect squares?',4,'The factorisation is 360=2³×3²×5. A square divisor uses even exponents. For 2 choose 0 or 2; for 3 choose 0 or 2; for 5 only 0. There are 2×2×1=4 square divisors: 1,4,9,36.','DIV-01',check=sum(math.isqrt(d)**2==d for d in divisors(360))))
 p.append(item('A clock gains 3 minutes every hour. It is set correctly at noon on Monday. After how many real hours will its 12-hour display next show the correct time?',240,'The display repeats every 12 hours, so it will look correct again when its accumulated gain is 12 hours=720 minutes. Gaining 3 minutes each real hour takes 720÷3=240 hours. A smaller positive gain cannot align both hands with the correct display.','RATE-04',check=720//3))
 p.append(item('A bag contains 5 red, 6 blue and 7 green counters. How many counters must be drawn without looking to guarantee at least three of each colour?',16,'To avoid three red counters, one could take all 13 non-red counters and only 2 red, a total of 15. Avoiding three blue allows at most 14; avoiding three green at most 13. Therefore 15 can still fail, but 16 guarantees all three colour counts are at least three.','LOGIC-03',check=max(18-k+2 for k in [5,6,7])+1))
 p.append(item('Eight squares in a row are coloured black or white. Exactly four are black, and no three consecutive squares may all be black. How many colourings are possible?',45,'Arrange the four white squares first; they create five gaps for black runs. Distributing four black squares freely among five gaps gives 8 choose 4=70 possibilities. A forbidden gap with at least three black squares is chosen in 5 ways; after reserving three there are 5 choices for the remaining black square, including the same gap. Two forbidden gaps cannot occur with only four black squares. Hence 70−5×5=45.','COUNT-06',check=sum(sum(z)==4 and '111' not in ''.join(map(str,z)) for z in product([0,1],repeat=8))))
 pts=list(product(range(4),repeat=2))
 p.append(item('Sixteen points form a 4-by-4 square array. How many different triangles have vertices chosen from these points?',516,'Choose any three points: 16×15×14÷6=560 triples. Subtract collinear triples. Four rows and four columns each contain 4 choose 3=4, giving 32. In each diagonal direction there is one length-4 diagonal (4 triples) and two length-3 diagonals (1 each), giving 12 more. No other slope contains three points in this small array. Thus 560−32−12=516 triangles.','COUNT-04',check=sum((b[0]-a[0])*(c[1]-a[1])!=(b[1]-a[1])*(c[0]-a[0]) for a,b,c in combinations(pts,3)),figure=svg(''.join(f'<circle cx="{85+70*x}" cy="{35+55*y}" r="4"/>' for x,y in pts))))
 return [one,paper('amc',6,p)]
